-- ADR-0197: tabela oficial de CEST (Convênio ICMS 142/2018, Anexos II a XXV) + cest_candidatos.
-- GLOBAL, sem org_id, de propósito: é dado público e igual para toda org. Escrita só service_role;
-- atualização por nova migration (`supabase migration new cest_refresh_<AAAAMMDD>` + `supabase db push`).
create table if not exists public.cest_oficial (
  cest text not null check (cest ~ '^[0-9]{7}$'),
  ncm_prefixo text not null check (ncm_prefixo ~ '^[0-9]{4,8}$'),
  anexo text not null,
  item text not null,
  descricao text not null,
  atualizado_em timestamptz not null default now(),
  primary key (cest, ncm_prefixo)
);

alter table public.cest_oficial enable row level security;
-- `create policy` não tem `if not exists`; o drop antes torna o re-run seguro (db push não é transacional).
drop policy if exists "cest_oficial: select autenticado" on public.cest_oficial;
create policy "cest_oficial: select autenticado"
  on public.cest_oficial for select to authenticated using (true);
grant select on public.cest_oficial to authenticated;

-- Todas as correspondências do NCM, do prefixo mais longo ao mais curto. O comprimento ordena e nunca
-- exclui: um prefixo curto pode descrever outra mercadoria do mesmo NCM (ADR-0197 D-2).
create or replace function public.cest_candidatos(p_ncm text)
returns table (cest text, ncm_prefixo text, descricao text, exato boolean)
language sql stable
set search_path = ''
as $$
  select c.cest, c.ncm_prefixo, c.descricao, length(c.ncm_prefixo) = 8
  from public.cest_oficial c
  where p_ncm like c.ncm_prefixo || '%'
  order by length(c.ncm_prefixo) desc, c.cest
$$;
revoke all on function public.cest_candidatos(text) from public;
grant execute on function public.cest_candidatos(text) to authenticated, service_role;

-- Carga: `deno run --allow-read scripts/cest/gerar-sql.ts <html do CV142_18>`, baixado em 2026-11-07.
on conflict (cest, ncm_prefixo) do update set anexo = excluded.anexo, item = excluded.item, descricao = excluded.descricao;
